package nl.atlas.gallery

/**
 * One deliberately small, data-free diagnostic for a failed MediaStore scan.
 *
 * Never append a provider exception, stack trace, exception message, URI,
 * storage path, provider volume or gallery row to Android logs. The code is
 * selected from a fixed enumeration, not from untrusted Throwable.toString().
 * Reporting does not change permission gates, publication or retry policy.
 */
/**
 * Typed markers for failures generated by OUR catalogue validation, not
 * provider-supplied exception text. Both remain IllegalStateExceptions to
 * preserve the existing catch/publication behavior.
 */
internal class GalleryProviderSnapshotChanged :
    IllegalStateException("Media provider changed during catalogue scan")

internal class GalleryProviderVersionUnavailable :
    IllegalStateException("Media provider version unavailable during scan")

internal enum class GalleryScanFailureCode {
    SNAPSHOT_CHANGED, VERSION_UNAVAILABLE,
    SECURITY, PROVIDER_BUSY, SQLITE, PROVIDER_CANCELLED,
    PROVIDER_IPC, PROVIDER_STATE, INVALID_ROW, IO, UNKNOWN
}

internal enum class GalleryScanGrantMatch { SAME, DIFFERENT, UNKNOWN }

internal class GalleryScanFailureEvidence(
    val code: GalleryScanFailureCode,
    val observerChanged: Boolean,
    val grantMatch: GalleryScanGrantMatch,
    val latestRequest: Boolean,
    val explicitlyRevoked: Boolean,
    val elapsedSeconds: Long
) {
    /** Safe to pass as the entire message to android.util.Log, never with a Throwable. */
    fun safeLogLine(ticket: Long): String {
        require(ticket > 0L)
        return "event=failed ticket=$ticket code=${code.name} " +
            "observer_changed=$observerChanged grant=${grantMatch.name} " +
            "latest=$latestRequest revoked=$explicitlyRevoked elapsed_s=$elapsedSeconds"
    }
}

/** Clamp anomalous clocks and lengthy provider stalls, never print wall-clock time. */
internal fun galleryScanElapsedSeconds(milliseconds: Long): Long =
    (milliseconds.coerceAtLeast(0L) / 1000L).coerceAtMost(600L)

/**
 * Classify only known Java/Android exception TYPES using their exact class
 * names; there is no inspection, interpolation or logging of any message.
 * Unknown vendor subclasses fail to a fixed UNKNOWN classification.
 */
internal fun galleryScanFailureEvidence(
    cause: Exception,
    observerChanged: Boolean,
    grantAtStartStillMatches: Boolean?,
    latestRequest: Boolean,
    explicitlyRevoked: Boolean,
    elapsedMilliseconds: Long
): GalleryScanFailureEvidence {
    val code = when {
        cause is GalleryProviderSnapshotChanged -> GalleryScanFailureCode.SNAPSHOT_CHANGED
        cause is GalleryProviderVersionUnavailable -> GalleryScanFailureCode.VERSION_UNAVAILABLE
        cause is SecurityException -> GalleryScanFailureCode.SECURITY
        cause.javaClass.name in setOf(
            "android.database.sqlite.SQLiteDatabaseLockedException",
            "android.database.sqlite.SQLiteDatabaseBusyException"
        ) -> GalleryScanFailureCode.PROVIDER_BUSY
        cause.javaClass.name == "android.database.sqlite.SQLiteException" ->
            GalleryScanFailureCode.SQLITE
        cause.javaClass.name == "android.os.OperationCanceledException" ->
            GalleryScanFailureCode.PROVIDER_CANCELLED
        cause.javaClass.name == "android.os.DeadObjectException" ->
            GalleryScanFailureCode.PROVIDER_IPC
        cause is IllegalStateException -> GalleryScanFailureCode.PROVIDER_STATE
        cause is IllegalArgumentException -> GalleryScanFailureCode.INVALID_ROW
        cause is java.io.IOException -> GalleryScanFailureCode.IO
        else -> GalleryScanFailureCode.UNKNOWN
    }
    return GalleryScanFailureEvidence(
        code, observerChanged,
        when (grantAtStartStillMatches) {
            true -> GalleryScanGrantMatch.SAME
            false -> GalleryScanGrantMatch.DIFFERENT
            null -> GalleryScanGrantMatch.UNKNOWN
        },
        latestRequest, explicitlyRevoked,
        galleryScanElapsedSeconds(elapsedMilliseconds)
    )
}

/** A successful publication marker makes fail-then-recover observable. */
internal fun galleryScanPublicationLogLine(ticket: Long, elapsedMilliseconds: Long): String {
    require(ticket > 0L)
    return "event=published ticket=$ticket elapsed_s=${galleryScanElapsedSeconds(elapsedMilliseconds)}"
}
